import React, { useEffect, useState, useRef } from 'react';
import { FaPlane } from 'react-icons/fa';
import { useTheme } from '../context/ThemeContext';
import { createNoise2D } from 'simplex-noise';

const DecorativePlanes = () => {
  const { theme } = useTheme();
  const [planes, setPlanes] = useState([]);
  const noise2D = useRef(createNoise2D());
  const frameRef = useRef(0);
  const animationFrameRef = useRef();

  class Plane {
    constructor(id) {
      this.id = id;
      this.size = 8 + Math.random() * 10;
      this.angle = Math.random() * Math.PI * 2;
      this.speed = 0.7 + Math.random() * 1.5;
      this.noiseSeed = Math.random() * 1000;
      this.turnStrength = 0.03 + Math.random() * 0.07;
      this.noiseTimeFactor = 0.005;

      // Initial position logic
      if (Math.random() < 0.25) {
        const edge = Math.floor(Math.random() * 4);
        if (edge === 0) { // Top
          this.x = Math.random() * 100;
          this.y = -this.size;
        } else if (edge === 1) { // Bottom
          this.x = Math.random() * 100;
          this.y = 100 + this.size;
        } else if (edge === 2) { // Left
          this.x = -this.size;
          this.y = Math.random() * 100;
        } else { // Right
          this.x = 100 + this.size;
          this.y = Math.random() * 100;
        }
      } else {
        this.x = Math.random() * 100;
        this.y = Math.random() * 100;
      }
    }

    update() {
      // Calculate angle change using noise
      const time = frameRef.current * this.noiseTimeFactor;
      const angleChange = (noise2D.current(this.noiseSeed + time, 0) - 0.5) * 2 * this.turnStrength;
      this.angle += angleChange;

      // Update position
      this.x += Math.cos(this.angle) * this.speed;
      this.y += Math.sin(this.angle) * this.speed;

      // Screen wrapping
      if (this.x < -this.size) this.x = 100 + this.size;
      if (this.x > 100 + this.size) this.x = -this.size;
      if (this.y < -this.size) this.y = 100 + this.size;
      if (this.y > 100 + this.size) this.y = -this.size;
    }
  }

  useEffect(() => {
    // Initialize planes
    const initialPlanes = Array.from({ length: 15 }, (_, index) => new Plane(index));
    setPlanes(initialPlanes);

    // Animation loop
    const animate = () => {
      frameRef.current++;
      setPlanes(currentPlanes => 
        currentPlanes.map(plane => {
          plane.update();
          return { ...plane };
        })
      );
      animationFrameRef.current = requestAnimationFrame(animate);
    };

    animationFrameRef.current = requestAnimationFrame(animate);

    return () => {
      if (animationFrameRef.current) {
        cancelAnimationFrame(animationFrameRef.current);
      }
    };
  }, []);

  return (
    <div className="fixed inset-0 pointer-events-none overflow-hidden" style={{ zIndex: 0 }}>
      {planes.map(plane => (
        <div
          key={plane.id}
          className="absolute"
          style={{
            left: `${plane.x}%`,
            top: `${plane.y}%`,
            transform: `rotate(${plane.angle * (180 / Math.PI)}deg)`,
            transition: 'transform 0.1s linear',
            opacity: 0.3,
            color: theme.primary
          }}
        >
          <FaPlane size={plane.size} />
        </div>
      ))}
    </div>
  );
};

export default DecorativePlanes;
